package com.whaa.shop.payment.application;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.baomidou.mybatisplus.extension.plugins.pagination.Page;import com.whaa.shop.common.api.PageResponse;import com.whaa.shop.payment.domain.PaymentRecord;import com.whaa.shop.payment.infrastructure.PaymentRecordMapper;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.LocalDateTime;
@Service public class PaymentRecordService {private final PaymentRecordMapper records;public PaymentRecordService(PaymentRecordMapper r){records=r;}@Transactional public void pending(Long orderId,BigDecimal amount){PaymentRecord r=records.selectOne(new LambdaQueryWrapper<PaymentRecord>().eq(PaymentRecord::getOrderId,orderId).eq(PaymentRecord::getProvider,"ALIPAY"));if(r==null){r=new PaymentRecord();r.setOrderId(orderId);r.setProvider("ALIPAY");r.setStatus("PENDING");r.setAmount(amount);r.setCreatedAt(LocalDateTime.now());r.setUpdatedAt(LocalDateTime.now());records.insert(r);}}@Transactional public void paid(Long orderId,String tradeNo){PaymentRecord r=records.selectOne(new LambdaQueryWrapper<PaymentRecord>().eq(PaymentRecord::getOrderId,orderId).eq(PaymentRecord::getProvider,"ALIPAY"));if(r!=null){r.setStatus("PAID");r.setTradeNo(tradeNo);r.setUpdatedAt(LocalDateTime.now());records.updateById(r);}}public PageResponse<PaymentRecord> page(long page,long size,String status){var q=new LambdaQueryWrapper<PaymentRecord>().eq(status!=null&&!status.isBlank(),PaymentRecord::getStatus,status).orderByDesc(PaymentRecord::getCreatedAt);Page<PaymentRecord> p=records.selectPage(Page.of(page,size),q);return new PageResponse<>(p.getRecords(),p.getTotal(),page,size);}}
